// Material code: runs once per hit (cheap), after the fields above are put into m.
//   m        the Material2 to change -- m.baseColor, m.roughness, m.metallic, m.emissive, ...
//   p, n     the hit point and surface normal, world space;  C  the Hit
//   p_local  the hit in the object's own frame, so a pattern moves with the object
//            (costs one extra SDF evaluation per hit on this material)
//   R_local  that frame's rotation to the world, for a direction written in it
//   S_local  its scale: p_local * S_local is in scene units, and metres(x) is x m in them
//   your own parameters (+ in the parameters header) by name, e.g. a colour stripe
// e.g. a checker fixed in the world:
//   m.baseColor = mix(m.baseColor, VEC3(0.05), step(0.0, sin(p.x * 3.0) * sin(p.y * 3.0) * sin(p.z * 3.0)));
// e.g. stripes that travel with the object:
//   m.roughness = step(0.5, fract(p_local.x * 4.0)) * 0.6;
// e.g. brushed along the object's x, for an anisotropy above 0 (or turned: grainAround):
//   m.tangent = grainAlong(R_local, VEC3(1.0, 0.0, 0.0));
// e.g. with a number width and a colour stripe added with +:
//   m.baseColor = mix(m.baseColor, stripe, step(fract(p.x / width), 0.5));

// Material code: runs once per hit (cheap), after the fields above are put into m.
//   m        the Material2 to change -- m.baseColor, m.roughness, m.metallic, m.emissive, ...
//   p, n     the hit point and surface normal, world space;  C  the Hit
//   p_local  the hit in the object's own frame, so a pattern moves with the object
//            (costs one extra SDF evaluation per hit on this material)
//   R_local  that frame's rotation to the world, for a direction written in it
//   S_local  its scale: p_local * S_local is in scene units, and metres(x) is x m in them
//   your own parameters (+ in the parameters header) by name, e.g. a colour stripe
// e.g. a checker fixed in the world:
//   m.baseColor = mix(m.baseColor, VEC3(0.05), step(0.0, sin(p.x * 3.0) * sin(p.y * 3.0) * sin(p.z * 3.0)));
// e.g. stripes that travel with the object:
//   m.roughness = step(0.5, fract(p_local.x * 4.0)) * 0.6;
// e.g. brushed along the object's x, for an anisotropy above 0 (or turned: grainAround):
//   m.tangent = grainAlong(R_local, VEC3(1.0, 0.0, 0.0));
// e.g. with a number width and a colour stripe added with +:
//   m.baseColor = mix(m.baseColor, stripe, step(fract(p.x / width), 0.5));

// vnoise3: value noise, [-1, 1]. Two colours and a roughness by its value.
let q = p_local * S_local * perMm(1.0 / 8.0);   // one cell every 8 mm, moving with the object
let t = 0.5 + 0.5 * vnoise3(q, 1u).w;
m.baseColor = mix(VEC3(0.12, 0.22, 0.55), VEC3(0.9, 0.85, 0.7), t);
m.roughness = mix(0.15, 0.8, t);

// gnoise3: gradient noise, about [-1, 1]: smoother and less grid-bound than value noise.
let q = p_local * S_local * perMm(1.0 / 8.0);   // one cell every 8 mm, moving with the object
let t = 0.5 + 0.5 * gnoise3(q, 2u).w;
m.baseColor = mix(VEC3(0.55, 0.12, 0.1), VEC3(0.95, 0.8, 0.3), t);
m.roughness = mix(0.15, 0.8, t);

// fbm3: five octaves, bending sine bands into veins -- polished marble.
let q = p_local * S_local * perMm(1.0 / 20.0);   // one cell every 20 mm, moving with the object
let n = fbm3(q, 3u, 5u, 2.0, 0.5);
let v = pow(1.0 - abs(sin(3.0 * (q.x + 1.6 * n.w))), 6.0);
m.baseColor = mix(VEC3(0.92, 0.91, 0.88), VEC3(0.25, 0.27, 0.3), v);

// worley3 F1: the distance to the nearest cell point -- round spots at each point.
let q = p_local * S_local * perMm(1.0 / 10.0);   // one cell every 10 mm, moving with the object
let w = worley3(q, 4u);
m.baseColor = mix(VEC3(0.1, 0.35, 0.2), VEC3(0.9, 0.9, 0.8), smoothstep(0.18, 0.24, w.x));

// worley3 F2 - F1: zero on a cell border -- the creases of grained leather, rougher and darker.
let q = p_local * S_local * perMm(1.0 / 2.5);   // one cell every 2.5 mm, moving with the object
let w = worley3(q, 5u);
let crease = 1.0 - smoothstep(0.0, 0.12, w.y - w.x);
m.baseColor = mix(VEC3(0.36, 0.2, 0.1), VEC3(0.12, 0.06, 0.03), crease);
m.roughness = mix(0.45, 0.85, crease);

// worley3 cell number: each grain its own mineral -- dark, pink or light -- as in granite.
let q = p_local * S_local * perMm(1.0 / 3.0);   // one cell every 3 mm, moving with the object
let w = worley3(q, 6u);
let c = select(select(VEC3(0.85, 0.83, 0.8), VEC3(0.75, 0.5, 0.45), w.z < 0.6), VEC3(0.08, 0.08, 0.09), w.z < 0.3);
m.baseColor = c * (0.85 + 0.15 * smoothstep(0.0, 0.1, w.y - w.x));

